diff --git a/tmp/sv-91ca2e2d70f64e6da7ce61c70d4052eb/UniversityCourseCatalog/Components/Layout/MainLayout.razor.css b/tmp/sv-91ca2e2d70f64e6da7ce61c70d4052eb/UniversityCourseCatalog/Components/Layout/MainLayout.razor.css
