namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = "CS", Name = "Computer Science", Description = "Explore the theory and practice of computing, from algorithms and data structures to software engineering and artificial intelligence." },
            new() { Id = "MATH", Name = "Mathematics", Description = "Study the abstract science of number, quantity, and space, whether as pure concepts or applied to other disciplines." },
            new() { Id = "PHYS", Name = "Physics", Description = "Investigate the fundamental principles governing matter, energy, and the forces of nature through theory and experimentation." },
            new() { Id = "ENGL", Name = "English", Description = "Develop critical reading, analytical writing, and literary interpretation skills across a broad range of texts and traditions." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Bio = "Dr. Chen has over 20 years of experience in software engineering and distributed systems. She has published extensively in top-tier conferences and holds several patents in cloud computing.", Email = "achen@greenfield.edu" },
            new() { Id = 2, Name = "Dr. Robert Kim", Title = "Associate Professor", Bio = "Dr. Kim specializes in machine learning and computer vision. Before joining academia, he spent eight years at a leading tech company working on image recognition systems.", Email = "rkim@greenfield.edu" },
            new() { Id = 3, Name = "Dr. Maria Garcia", Title = "Professor", Bio = "Dr. Garcia is an accomplished mathematician whose research focuses on topology and abstract algebra. She has received multiple national awards for excellence in teaching.", Email = "mgarcia@greenfield.edu" },
            new() { Id = 4, Name = "Dr. James Wilson", Title = "Assistant Professor", Bio = "Dr. Wilson is a number theorist with a passion for making mathematics accessible. He regularly contributes to popular science publications and hosts a math outreach podcast.", Email = "jwilson@greenfield.edu" },
            new() { Id = 5, Name = "Dr. Sarah Patel", Title = "Professor", Bio = "Dr. Patel is a renowned experimental physicist specializing in quantum optics. Her lab has produced groundbreaking research on photon entanglement and quantum information.", Email = "spatel@greenfield.edu" },
            new() { Id = 6, Name = "Dr. David Nguyen", Title = "Associate Professor", Bio = "Dr. Nguyen studies condensed matter physics with a focus on superconducting materials. He has collaborated with national laboratories on next-generation energy research.", Email = "dnguyen@greenfield.edu" },
            new() { Id = 7, Name = "Dr. Emily Brooks", Title = "Professor", Bio = "Dr. Brooks is a literary scholar specializing in 19th-century American literature. She has authored three books and serves on the editorial board of two prestigious literary journals.", Email = "ebrooks@greenfield.edu" },
            new() { Id = 8, Name = "Dr. Michael Torres", Title = "Assistant Professor", Bio = "Dr. Torres focuses on creative writing and contemporary fiction. His debut novel was shortlisted for a national book award, and he leads the university's creative writing workshop.", Email = "mtorres@greenfield.edu" }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented design. No prior experience required.", DepartmentId = "CS", Credits = 3, Schedule = "MWF 10:00-10:50 AM", Location = "Science Hall 201", InstructorId = 1, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = "CS201", Title = "Data Structures & Algorithms", Description = "Study essential data structures including arrays, linked lists, trees, graphs, and hash tables. Analyze algorithm complexity and learn sorting, searching, and graph algorithms.", DepartmentId = "CS", Credits = 4, Schedule = "TTh 1:00-2:20 PM", Location = "Science Hall 305", InstructorId = 1, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = "CS301", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and deep learning frameworks. Includes hands-on projects with real-world datasets.", DepartmentId = "CS", Credits = 3, Schedule = "TTh 3:00-4:20 PM", Location = "Tech Center 110", InstructorId = 2, IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
            new() { Id = "CS401", Title = "Software Engineering", Description = "Learn professional software development practices including agile methodologies, version control, testing strategies, CI/CD pipelines, and collaborative development workflows.", DepartmentId = "CS", Credits = 3, Schedule = "MWF 2:00-2:50 PM", Location = "Tech Center 215", InstructorId = 2, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32 },

            // Mathematics
            new() { Id = "MATH101", Title = "Calculus I", Description = "First course in calculus covering limits, continuity, derivatives, and an introduction to integration. Applications to physics, engineering, and the natural sciences.", DepartmentId = "MATH", Credits = 4, Schedule = "MWF 9:00-9:50 AM", Location = "Math Building 101", InstructorId = 3, IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = "MATH201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and inner product spaces. Essential for advanced work in math, physics, and computer science.", DepartmentId = "MATH", Credits = 3, Schedule = "TTh 10:00-11:20 AM", Location = "Math Building 203", InstructorId = 3, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 48 },
            new() { Id = "MATH301", Title = "Abstract Algebra", Description = "An introduction to algebraic structures including groups, rings, and fields. Emphasizes proof techniques and abstract mathematical reasoning.", DepartmentId = "MATH", Credits = 3, Schedule = "MWF 11:00-11:50 AM", Location = "Math Building 305", InstructorId = 4, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 22 },

            // Physics
            new() { Id = "PHYS101", Title = "General Physics I", Description = "Introduction to mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments and data analysis.", DepartmentId = "PHYS", Credits = 4, Schedule = "MWF 1:00-1:50 PM", Location = "Physics Lab 100", InstructorId = 5, IsFeatured = true, MaxEnrollment = 100, CurrentEnrollment = 85 },
            new() { Id = "PHYS201", Title = "Electromagnetism", Description = "Study of electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics. Builds on General Physics I with more advanced mathematical treatment.", DepartmentId = "PHYS", Credits = 4, Schedule = "TTh 9:00-10:20 AM", Location = "Physics Lab 200", InstructorId = 5, IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 38 },
            new() { Id = "PHYS301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave-particle duality, the Schrödinger equation, quantum states, and measurement. Prerequisites: PHYS201 and MATH201.", DepartmentId = "PHYS", Credits = 3, Schedule = "MWF 3:00-3:50 PM", Location = "Physics Lab 310", InstructorId = 6, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 25 },
            new() { Id = "PHYS401", Title = "Condensed Matter Physics", Description = "Explore the physics of solids and liquids including crystal structures, electronic band theory, semiconductors, and superconductivity.", DepartmentId = "PHYS", Credits = 3, Schedule = "TTh 2:00-3:20 PM", Location = "Physics Lab 310", InstructorId = 6, IsFeatured = false, MaxEnrollment = 25, CurrentEnrollment = 18 },

            // English
            new() { Id = "ENGL101", Title = "College Writing", Description = "Develop essential academic writing skills through critical reading, analytical essays, research papers, and revision workshops. Emphasis on clear argumentation and evidence-based writing.", DepartmentId = "ENGL", Credits = 3, Schedule = "MWF 10:00-10:50 AM", Location = "Humanities Hall 105", InstructorId = 7, IsFeatured = true, MaxEnrollment = 25, CurrentEnrollment = 24 },
            new() { Id = "ENGL201", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, democracy, and the American experience through major authors and movements.", DepartmentId = "ENGL", Credits = 3, Schedule = "TTh 11:00-12:20 PM", Location = "Humanities Hall 210", InstructorId = 7, IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 28 },
            new() { Id = "ENGL301", Title = "Creative Writing Workshop", Description = "An intensive workshop in fiction and poetry writing. Students produce original work, participate in peer critique sessions, and study craft elements through published examples.", DepartmentId = "ENGL", Credits = 3, Schedule = "W 2:00-4:50 PM", Location = "Humanities Hall 315", InstructorId = 8, IsFeatured = false, MaxEnrollment = 15, CurrentEnrollment = 14 }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? departmentId, string? searchTerm)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
            query = query.Where(c => c.DepartmentId == departmentId);

        if (!string.IsNullOrWhiteSpace(searchTerm))
            query = query.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public Instructor? GetInstructor(int id) =>
        _instructors.FirstOrDefault(i => i.Id == id);
}

