@page "/"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="welcome-banner text-center py-5 mb-4">
    <h1>Welcome to Greenfield University</h1>
    <p class="lead">Discover your path — explore our courses and start your journey today.</p>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row">
        @foreach (var course in featuredCourses)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="course-card h-100">
                    <h5><a href="/courses/@course.Id">@course.Title</a></h5>
                    <span class="badge bg-secondary">@course.DepartmentId</span>
                    <span class="badge bg-info text-dark">@course.Credits Credits</span>
                    <p class="mt-2 text-muted">
                        @(course.Description.Length > 100 ? course.Description[..100] + "…" : course.Description)
                    </p>
                </div>
            </div>
        }
    </div>
</section>

<section class="mb-5">
    <h2 class="mb-3">Departments</h2>
    <div class="list-group">
        @foreach (var dept in departments)
        {
            <a href="/courses?departmentId=@dept.Id" class="list-group-item list-group-item-action">
                <strong>@dept.Name</strong> — @dept.Description
            </a>
        }
    </div>
</section>

@code {
    private List<UniversityCourseCatalog.Models.Course> featuredCourses = new();
    private List<UniversityCourseCatalog.Models.Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<form method="get" action="/courses" class="search-filter-bar mb-4">
    <div class="row g-2 align-items-end">
        <div class="col-md-5">
            <label for="searchTerm" class="form-label">Search</label>
            <input type="text" id="searchTerm" name="searchTerm" class="form-control" placeholder="Search by title or description…" value="@SearchTerm" />
        </div>
        <div class="col-md-4">
            <label for="departmentId" class="form-label">Department</label>
            <select id="departmentId" name="departmentId" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id" selected="@(dept.Id == DepartmentId)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-3">
            <button type="submit" class="btn btn-primary w-100">Search</button>
        </div>
