@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService
@inject UniversityCourseCatalog.Services.EnrollmentService EnrollmentService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (IsSubmitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p><strong>Student:</strong> @Model.StudentName (@Model.StudentId)</p>
        <p><strong>Course:</strong> @Model.CourseId</p>
        @if (!string.IsNullOrWhiteSpace(Model.Comments))
        {
            <p><strong>Comments:</strong> @Model.Comments</p>
        }
        <p><strong>Submitted at:</strong> @Model.SubmittedAt.ToString("f")</p>
        <a href="/courses" class="btn btn-primary mt-2">Back to Course Catalog</a>
    </div>
}
else
{
    <form method="post" class="needs-validation" style="max-width: 600px;">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Student Name <span class="text-danger">*</span></label>
            <input type="text" id="studentName" name="Model.StudentName" class="form-control" required value="@Model.StudentName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
            <input type="text" id="studentId" name="Model.StudentId" class="form-control" required value="@Model.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
            <select id="courseId" name="Model.CourseId" class="form-select" required>
                <option value="">— Select a course —</option>
                @foreach (var course in allCourses)
                {
                    <option value="@course.Id" selected="@(course.Id == SelectedCourseId)">@course.Id - @course.Title</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label for="comments" class="form-label">Comments</label>
            <textarea id="comments" name="Model.Comments" class="form-control" rows="3">@Model.Comments</textarea>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromQuery(Name = "courseId")]
    public string? CourseIdQuery { get; set; }

    [SupplyParameterFromForm]
    public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    private List<UniversityCourseCatalog.Models.Course> allCourses = new();
    private string? SelectedCourseId;
    private bool IsSubmitted;

    protected override void OnInitialized()
    {
        allCourses = CatalogService.GetCourses(null, null);
        SelectedCourseId = Model.CourseId;

        if (string.IsNullOrEmpty(SelectedCourseId) && !string.IsNullOrEmpty(CourseIdQuery))
        {
            SelectedCourseId = CourseIdQuery;
            Model.CourseId = CourseIdQuery;
        }

        if (HttpMethods.IsPost(HttpContext.Request.Method)
            && !string.IsNullOrWhiteSpace(Model.StudentName)
            && !string.IsNullOrWhiteSpace(Model.StudentId)
            && !string.IsNullOrWhiteSpace(Model.CourseId))
        {
            EnrollmentService.SubmitRequest(Model);
            IsSubmitted = true;
        }
    }

    [CascadingParameter]
    public HttpContext HttpContext { get; set; } = default!;
}

