 <PageTitle>Course Catalog</PageTitle>

 <h1 class="mb-4">Course Catalog</h1>

 <form method="get" action="/courses" class="search-filter-bar mb-4">
     <div class="row g-2 align-items-end">
         <div class="col-md-5">
             <label for="searchTerm" class="form-label">Search</label>
             <input type="text" id="searchTerm" name="searchTerm" class="form-control" placeholder="Search by title or description…" value="@SearchTerm" />
         </div>
         <div class="col-md-4">
             <label for="departmentId" class="form-label">Department</label>
             <select id="departmentId" name="departmentId" class="form-select">
                 <option value="">All Departments</option>
                 @foreach (var dept in departments)
                 {
                     <option value="@dept.Id" selected="@(dept.Id == DepartmentId)">@dept.Name</option>
                 }
             </select>
         </div>
         <div class="col-md-3">
             <button type="submit" class="btn btn-primary w-100">Search</button>
         </div>
     </div>
 </form>

 @if (courses.Any())
 {
     <div class="table-responsive">
         <table class="table table-striped table-hover">
             <thead class="table-dark">
                 <tr>
                     <th>ID</th>
                     <th>Title</th>
                     <th>Department</th>
                     <th>Credits</th>
                     <th>Schedule</th>
                 </tr>
             </thead>
             <tbody>
                 @foreach (var course in courses)
                 {
                     <tr>
                         <td>@course.Id</td>
                         <td><a href="/courses/@course.Id">@course.Title</a></td>
                         <td>@course.DepartmentId</td>
                         <td>@course.Credits</td>
                         <td>@course.Schedule</td>
                     </tr>
                 }
             </tbody>
         </table>
     </div>
 }
 else
 {
     <div class="alert alert-info">No courses found matching your criteria.</div>
 }

