 @page "/courses/{CourseId}"
 @inject UniversityCourseCatalog.Services.CatalogService CatalogService

 @if (course is null)
 {
     <PageTitle>Course Not Found</PageTitle>
     <div class="alert alert-warning">
         <h4>Course Not Found</h4>
         <p>The course you're looking for does not exist. <a href="/courses">Browse all courses</a>.</p>
     </div>
 }
 else
 {
     <PageTitle>@course.Title — Greenfield University</PageTitle>

     <nav aria-label="breadcrumb" class="mb-3">
         <ol class="breadcrumb">
             <li class="breadcrumb-item"><a href="/">Home</a></li>
             <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
             <li class="breadcrumb-item active" aria-current="page">@course.Id</li>
         </ol>
     </nav>

     <div class="detail-page">
         <h1>@course.Title</h1>
         <span class="badge bg-secondary fs-6 me-2">@course.Id</span>
         <span class="badge bg-info text-dark fs-6">@course.Credits Credits</span>

         <p class="mt-3">@course.Description</p>

         <div class="row mt-4">
             <div class="col-md-6">
                 <h5>Details</h5>
                 <ul class="list-unstyled">
                     <li><strong>Schedule:</strong> @course.Schedule</li>
                     <li><strong>Location:</strong> @course.Location</li>
                     <li><strong>Department:</strong> <a href="/courses?departmentId=@course.DepartmentId">@(department?.Name ?? course.DepartmentId)</a></li>
                     <li><strong>Enrollment:</strong> @course.CurrentEnrollment / @course.MaxEnrollment</li>
                 </ul>
             </div>

             @if (instructor is not null)
             {
                 <div class="col-md-6">
                     <h5>Instructor</h5>
                     <p><strong>@instructor.Name</strong> — @instructor.Title</p>
                     <p>@instructor.Bio</p>
                     <p><a href="mailto:@instructor.Email">@instructor.Email</a></p>
                 </div>
             }
         </div>

         <div class="mt-4">
             <a href="/enroll?courseId=@course.Id" class="btn btn-primary btn-lg">Enroll in this Course</a>
         </div>
     </div>
 }

 @code {
     [Parameter] public string CourseId { get; set; } = "";

     private UniversityCourseCatalog.Models.Course? course;
     private UniversityCourseCatalog.Models.Department? department;
     private UniversityCourseCatalog.Models.Instructor? instructor;

     protected override void OnInitialized()
     {
         course = CatalogService.GetCourse(CourseId);
         if (course is not null)
         {
             department = CatalogService.GetDepartment(course.DepartmentId);
             instructor = CatalogService.GetInstructor(course.InstructorId);
         }
     }
 }

